import re
from typing import Dict, Any

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    result: Dict[str, Dict[str, str]] = {}
    current_section = None
    last_key = None
    default_section: Dict[str, str] = {}

    # Track interpolation references to detect cycles
    interpolation_stack = set()

    def interpolate_value(value: str, section: str, seen: set) -> str:
        if not value:
            return value

        # Detect recursion
        if (section, value) in seen:
            raise ValueError("Interpolation cycle detected")
        seen.add((section, value))

        # Find all ${key} and ${section:key} patterns
        pattern = r'\$\{([^}]+)\}'
        matches = list(re.finditer(pattern, value))

        if not matches:
            return value

        # Process from right to left to avoid index shifting issues
        result_str = value
        for match in reversed(matches):
            full_match = match.group(0)
            key_ref = match.group(1)

            # Parse section:key or just key
            if ':' in key_ref:
                ref_section, ref_key = key_ref.split(':', 1)
                ref_section = ref_section.strip()
                ref_key = ref_key.strip()
            else:
                ref_section = section
                ref_key = key_ref.strip()

            # Check if key exists in current section or inherited from DEFAULT
            if ref_section not in result and ref_section != "DEFAULT":
                raise KeyError(f"Section '{ref_section}' not found")

            # Look for the key in the specified section
            target_section = result.get(ref_section, {})
            if ref_section == "DEFAULT":
                target_section = default_section

            if ref_key.lower() not in target_section:
                raise KeyError(f"Key '{ref_key}' not found in section '{ref_section}'")

            # Get the value and recursively interpolate it
            target_value = target_section[ref_key.lower()]
            interpolated_value = interpolate_value(target_value, ref_section, seen.copy())

            # Replace the reference
            result_str = result_str[:match.start()] + interpolated_value + result_str[match.end():]

        return result_str

    for line_num, line in enumerate(lines, 1):
        # Skip empty lines and comments
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith((';', '#')):
            continue

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            section_name = stripped_line[1:-1].strip()
            if section_name == "DEFAULT":
                current_section = "DEFAULT"
                continue
            else:
                current_section = section_name
                result[section_name] = {}
                last_key = None
                continue

        # Check for key-value pair
        if '=' in line or ':' in line:
            # Find the first occurrence of = or :
            eq_pos = line.find('=')
            colon_pos = line.find(':')

            if eq_pos == -1:
                sep_pos = colon_pos
                sep_char = ':'
            elif colon_pos == -1:
                sep_pos = eq_pos
                sep_char = '='
            else:
                sep_pos = min(eq_pos, colon_pos)
                sep_char = line[sep_pos]

            # Check if separator is inside quotes
            quote_count = 0
            in_quotes = False
            for i, char in enumerate(line):
                if char == '"' and (i == 0 or line[i-1] != '\\'):
                    in_quotes = not in_quotes
                if i == sep_pos and in_quotes:
                    # Separator is inside quotes, continue searching
                    if sep_char == '=':
                        eq_pos = line.find('=', i + 1)
                        if eq_pos != -1:
                            sep_pos = eq_pos
                            sep_char = '='
                    else:
                        colon_pos = line.find(':', i + 1)
                        if colon_pos != -1:
                            sep_pos = colon_pos
                            sep_char = ':'
                    break

            # Split on the separator
            key_part = line[:sep_pos]
            value_part = line[sep_pos + 1:]

            # Extract key and value
            key = key_part.strip().lower()
            value = value_part.rstrip()

            # Check for inline comments outside quotes
            in_quotes = False
            for i, char in enumerate(value):
                if char == '"' and (i == 0 or value[i-1] != '\\'):
                    in_quotes = not in_quotes
                elif not in_quotes and char in ';#' and (i == 0 or value[i-1] == ' '):
                    value = value[:i]
                    break

            # Handle quoted values
            if value.startswith('"') and value.endswith('"') and len(value) >= 2:
                # Remove quotes but preserve content exactly
                value = value[1:-1]
            else:
                # Strip whitespace for non-quoted values
                value = value.strip()

            # Add to current section
            if current_section is None:
                raise ValueError("Key-value pair found before any section header")

            if current_section == "DEFAULT":
                default_section[key] = value
            else:
                result[current_section][key] = value
            last_key = key
            continue

        # Handle continuation lines (starting with whitespace)
        if line.startswith((' ', '\t')) and last_key is not None:
            # Remove leading whitespace and handle inline comments
            stripped_line = line.lstrip()
            in_quotes = False
            for i, char in enumerate(stripped_line):
                if char == '"' and (i == 0 or stripped_line[i-1] != '\\'):
                    in_quotes = not in_quotes
                elif not in_quotes and char in ';#' and (i == 0 or stripped_line[i-1] == ' '):
                    stripped_line = stripped_line[:i]
                    break

            # Append to previous value with newline
            if current_section == "DEFAULT":
                default_section[last_key] += "\n" + stripped_line
            else:
                result[current_section][last_key] += "\n" + stripped_line
            continue

        # Malformed line
        raise ValueError(f"Malformed line at line {line_num}: {line}")

    # Apply DEFAULT section inheritance
    for section_name, section_data in result.items():
        for key, value in default_section.items():
            if key not in section_data:
                section_data[key] = value

    # Perform interpolation on all values
    for section_name, section_data in result.items():
        for key, value in list(section_data.items()):
            try:
                interpolation_stack.clear()
                interpolated_value = interpolate_value(value, section_name, interpolation_stack)
                section_data[key] = interpolated_value
            except ValueError as e:
                raise ValueError(f"Interpolation error in section '{section_name}', key '{key}': {str(e)}")
            except KeyError as e:
                raise KeyError(f"Interpolation error in section '{section_name}', key '{key}': {str(e)}")

    return result
