import re

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_totals = {}
    customer_names = {}

    for row in rows:
        customer = row.get("customer", "").strip()
        amount_str = row.get("amount", "").strip()

        if not customer:
            continue

        # Clean and parse amount
        cleaned_amount = amount_str.replace('$', '').replace(',', '')
        try:
            amount = float(cleaned_amount)
        except ValueError:
            continue

        # Use first valid occurrence's spelling (trimmed)
        customer_lower = customer.lower()
        if customer_lower not in customer_names:
            customer_names[customer_lower] = customer
        if customer_lower not in customer_totals:
            customer_totals[customer_lower] = 0.0
        customer_totals[customer_lower] += amount

    # Convert to list of tuples with original trimmed names
    result = [
        (customer_names[lower_name], round(total, 2))
        for lower_name, total in customer_totals.items()
    ]

    # Sort by total descending, then by name ascending
    result.sort(key=lambda x: (-x[1], x[0]))

    return result[:n]
